#!/usr/bin/env bash
# file-issues.sh — step 4 of the 3.1.0 audit: create the new issues (ids captured to new-issues.txt), label and parent them.
set -uo pipefail
cd /home/dwalleck/repos/cyril
OUT=experiments/conductor-spike/audit-3.1.0/orchestrator/new-issues.txt; : > "$OUT"
mk() { # key prio kind title description labels... 
  local key=$1 prio=$2 kind=$3 title=$4 desc=$5; shift 5
  local json; json=$(rivets create --json -y -p "$prio" -k "$kind" --title "$title" -D "$desc" 2>&1)
  local id; id=$(printf '%s' "$json" | grep -o -E 'cyril-[a-z0-9]{4}' | head -1)
  if [ -z "$id" ]; then echo "CREATE FAILED $key: $json" | head -3; return 1; fi
  echo "$key $id P$prio $title" >> "$OUT"; echo "$key -> $id"
  for l in "$@"; do rivets label add "$l" "$id" -y >/dev/null || echo "label $l failed on $id"; done
}
mk N1 2 bug "KAS 0.66.91: sub-agent replies stream on the parent session (agentSubtaskId) and cyril renders them as parent text" "Found by the kiro-cli 3.1.0 audit (docs/kiro-3.1.0-wire-audit.md §2a row 6, §8 LIVE-H; experiments/conductor-spike/kas-subagent-parent-stream-3.1.0.jsonl). On KAS 0.66.91 the child's reply is streamed as ordinary agent_message_chunk frames ON THE PARENT SESSION ID, distinguishable only by _meta.kiro.agentSubtaskId (+ executionId, turnId); the orphan tool_call_update 'Subagent Response' that cyril-1v25 learned to render is GONE (0 hits). cyril converts every parent chunk through the generic path (crates/cyril-core/src/protocol/convert/kas.rs:835 → convert/mod.rs:506 → Notification::AgentMessage) and never reads agentSubtaskId (0 production hits), so the user reads 'The word is: ALPHA (from PROBE.txt, line 1)ALPHA' as one parent message. Entry point: any prompt that makes KAS delegate (invoke_sub_agent) — default engine, no opt-in → P2. Fix: route chunks carrying _meta.kiro.agentSubtaskId to the sub-agent stream (SubagentUiState) keyed by agentSubtaskId, header it with the 'Sub-agent: <name>' tool call title, and retire the 1v25 orphan path for 0.66.91 while keeping it for 0.66.43. Extends cyril-ebqu (agent-subtask pipeline rendering). 0.66.43 behaviour: child streams no text; answer arrives as the orphan update (kas-lead-subagent-2.32.0.jsonl#89)." kas kiro-3-1-0 ready-for-agent
mk N2 2 feature "KAS session_usage: adopt the authoritative session credit total (replayed on session/load) for /usage and the footer" "kiro-cli 3.1.0 audit (docs/kiro-3.1.0-wire-audit.md §2a row 4, §3, §8 leg 1; experiments/conductor-spike/kas-live-sweep-3.1.0.jsonl). KAS 0.66.91 emits session_info_update {kind:\"session_usage\", credits:[{usage, unit?, unitPlural?}]} right after every turn_completion (sumCreditsByUnit over all promptTurnSummaries) and REPLAYS it (replay:true) on session/load — the 3.1.0 'footer total no longer resets' fix. cyril drops the kind at the kind-match fallthrough (crates/cyril-core/src/protocol/convert/kas.rs:822) and sums turn_completion itself (crates/cyril-core/src/session.rs:291 set_credit_usage; types/session.rs:627-662), so /usage 'Credits' and the footer restart at 0 after /load and never match Kiro's total (leg 5 V5: /usage shows per-turn credits only). Entry point: every metered turn, /usage, /load — default engine → P2. Fix: model Notification::SessionUsage, prefer it over the local sum when present (Kiro TUI's sessionCreditsReported semantics), keep the local sum for 0.66.43; share the credit-unit predicate (cyril-8alk)." kas kiro-3-1-0 ready-for-agent
mk N3 2 feature "KAS 0.66.91 workflow step credits and run progress on the wire: model credits[] and stepsCompleted/stepsTotal/currentNodeId/waitingOnWatch" "kiro-cli 3.1.0 audit (docs/kiro-3.1.0-wire-audit.md §4, §8 leg 2a; experiments/conductor-spike/kas-workflow-gateoff-3.1.0.jsonl#193 credits). Node state gains credits:[{usage,unit?,unitPlural?}]; node_complete carries the step's credits; run_complete carries credits summed by unit (runCompleteCreditFields); node credits == the step session's session_usage, run = sum (LIVE). Since 0.66.48 _kiro/workflow/list rows and every event carry stepsCompleted/stepsTotal/currentNodeId/waitingOnWatch while a run is running/paused. cyril drops all of them: WireNodeSnapshot crates/cyril-core/src/protocol/convert/kas/workflow.rs:444-520, WireNodeCompleted :259-283, WireRunCompleted :207-218, WireRunListEntry :588-618; run totals are a parent-metering estimate (crates/cyril-core/src/workflow.rs:487,1319; cyril-ui/src/turn_labels.rs:108-121). Entry point: every cyril-launched run (/workflow run, /review; gate-off) → P2. Fix: add the fields to the wire structs and WorkflowRun, show per-step credits in /workflow status and the run panel, prefer engine run credits over the estimate (cyril-2lh8 follow-up), show progress on /workflow list rows. Extends cyril-4u4a." kas w1 kiro-3-1-0 ready-for-agent
mk N4 2 bug "V2 wrapper spawn must pin --agent-engine v2: kiro-cli ≥2.36.0 routes 'kiro-cli acp' by clientInfo.name and a 3.x host hands the unlisted name cyril the v3 engine" "kiro-cli 3.1.0 audit (docs/kiro-3.1.0-wire-audit.md §5, §8 HOST-L1; experiments/conductor-spike/audit-3.1.0/live/host-engine-authclient-3.1.0.jsonl). Since 2.36.0 crates/chat-cli/src/cli/acp_engine.rs peeks the ACP initialize request and routes by clientInfo.name against an embedded snapshot of 1,080 client names that stay on v2 plus an exempt list (empty since 2.37.1); cyril is in neither list. LIVE on 3.1.0: a bare 'kiro-cli acp' from clientInfo.name cyril gets the v3 engine (node child spawned, _meta.kiro on initialize, 34 extensionMethods) despite --help's 'v2 when neither is set'; --agent-engine v2 or acp.agentEngine:\"v2\" restore v2. cyril's AgentEngine::V2 wrapper spawn is the user's bare agent command (crates/cyril-core/src/protocol/bridge.rs:394; default argv crates/cyril/src/main.rs:32-36), so on a 3.x install cyril's V2Engine receives KAS and protocol/fingerprint.rs:92-105 fails with a remedy that names the same command. Fix: append --agent-engine v2 to V2 wrapper spawns for kiro-cli ≥2.7.1 (reuse kas/version.rs:343-364 build_wrapper_command with flag v2), reword the fingerprint remedy, and document that the V2 engine is slated for removal 'in January' (Kiro's own 3.x prompt text). Not the default path (KAS Free never meets the router) → P2. Related cyril-a7nk, cyril-0rn8 (a logged-out 3.x 'kiro-cli acp' now answers initialize with authMethods kiro-login and refuses session/new -32000)." v2 kas kiro-3-1-0 ready-for-agent
mk N5 2 feature "Honour chat.workflowLaunch and expose KAS's workflowLaunch (Workflow use) option; sessions recorded before 0.66.58 load as delegate-all" "kiro-cli 3.1.0 audit (docs/kiro-3.1.0-wire-audit.md §4, §8 WF-L2; experiments/conductor-spike/kas-workflow-launch-option-3.1.0.jsonl). KAS 0.66.58 (2.33.1) adds a session config option {type:select, id:\"workflowLaunch\", name:\"Workflow use\", options when-asked 'When asked' / large-tasks 'Large tasks only' / delegate-all 'Delegate all work'}, default when-asked, offered only while settings.workflows.enabled; it drives a '# Workflow launch setting' system-prompt block. LIVE: round trip echoes currentValue; a session created by 0.66.43 and loaded by 0.66.91 runs as DELEGATE-ALL with no option offered (legacy). Kiro's TUI restores chat.workflowLaunch via set_config_option right after session/new and offers it under /settings Features. cyril: the select is dropped on receipt (KasConfigId::from_wire knows only model/mode/effortLevel, crates/cyril-core/src/types/kas_config.rs:20-48) and never set (cyril reads only chat.enableWorkflows, crates/cyril-core/src/protocol/kas/settings.rs:108-116,140-145; leg 5 S3: /mode has no such row). Entry point: chat.enableWorkflows=true (ADR-0013 decision 1: follow the user's Kiro setting — chat.workflowLaunch IS that setting) and /load of an older session → P2. Fix: read chat.workflowLaunch, send set_config_option {configId:\"workflowLaunch\"} after session/new when offered, let KasConfigId carry it, surface it in the /mode-class picker. Related cyril-xehm, cyril-0asq." kas w1 kiro-3-1-0 ready-for-agent
mk N6 3 feature "Session recap: map chat.enableSessionRecap to settings.sessionRecap and render the recap kind" "kiro-cli 3.1.0 audit (docs/kiro-3.1.0-wire-audit.md §3, §6, §8 TUI-L1; experiments/conductor-spike/audit-3.1.0/live/kas-lead-recap-3.1.0.jsonl). Kiro's TUI 3.1.0 sends initialize.clientCapabilities._meta.kiro.settings.sessionRecap:{enabled} from chat.enableSessionRecap (default false; '/settings Features — Session recap · one model call per turn'); KAS then runs startRecap() ~1 s after turn_end and pushes session_info_update {kind:\"recap\", text}. LIVE: the gate works on 0.66.91 AND the kind already exists on 0.66.43 (3.1.0 added only the TUI setting). cyril: settings.rs:77-95 has no sessionRecap row (NOT-SENT) and kas.rs:822 drops recap. Opt-in (one billed model call per turn) → P3. Fix: BOOL_MAP row chat.enableSessionRecap → sessionRecap, Notification::Recap, render above the input after idle (primary session only, as the TUI)." kas kiro-3-1-0 ready-for-agent
mk N7 3 feature "Approve for me on KAS (opt-in): set KIRO_TRUST_CLASSIFIER_MODE=enforce on the KAS child and render trustClassifierApproved rows" "kiro-cli 3.1.0 audit (docs/kiro-3.1.0-wire-audit.md §3, §6, §8 KAS-L4/TUI-L5; experiments/conductor-spike/kas-approve-for-me-3.1.0.jsonl). 'Approve for me' (2.36.0 changelog; KAS 0.66.58 code) is a trust classifier gated by env KIRO_TRUST_CLASSIFIER_MODE=enforce at KAS spawn plus a permissions rule {capability:\"all\", effect:\"evaluate\"} (new effect in the agent-file schema). LIVE on 0.66.91 with both: the shell call runs with tool_call_update._meta.kiro.trustClassifierApproved:true, a SECOND billed 'permission-classifier' model call, and NO session/request_permission; the decision:\"prompt\" branch (flag line + request_permission._meta.kiro.trustClassifier) was not reached. On 0.66.43 an evaluate rule is fatal (every tool denied). The TUI writes the rule via /permissions policies approve-for-me and shows the status segment approveForMe; it is dark unless the env is set (the trust_classifier_enforce rollout gate was removed in 3.1.0). cyril: spawn sets no env (kas/discovery.rs), convert/kas.rs:67-91 reads only consent/rejectionReason. Opt-in → P3. Fix shape: [agent] approve_for_me = true → env on the KAS child + 'approved by Kiro' badge on classifier-approved tool rows + flag line rendering." kas kiro-3-1-0 ready-for-agent
mk N8 3 feature "Interactive MCP elicitation: answer form and url elicitations like Kiro's TUI instead of a visible decline" "kiro-cli 3.1.0 audit (docs/kiro-3.1.0-wire-audit.md §3, §6 T8, §8 LIVE-B; experiments/conductor-spike/kas-mcp-elicitation-3.1.0.jsonl). KAS has called the host callback _kiro/mcp/elicitation {sessionId, toolCallId, elicitation:{mode:form|url, message, requestedSchema?|url?}} unconditionally since ≤0.66.43 (no mcpElicitation flag check; the TUI's flag is advisory) and mirrors it as tool_call_update status:pending _meta.kiro.elicitation. Kiro's TUI (2.34.0) answers forms with {action:\"accept\", content:{…}} driven by requestedSchema and links with Open in browser / I'll open it myself → {action:\"accept\"}, Decline, Cancel. cyril answers every elicitation with a visible, context-preserving decline (crates/cyril-core/src/protocol/kas/mcp.rs; callbacks.rs:597), so an MCP tool that needs input fails. Opt-in surface (only tools that elicit) → P3. Fix: a form overlay (Overlay variant, has_modal_overlay) built from requestedSchema.properties, a url overlay with open/copy, cancel on Esc; keep the decline as the fallback for malformed requests. Related cyril-dn91 (closed)." kas kiro-3-1-0 ready-for-agent
mk N9 3 bug "KAS discovery is blind to KIRO_RUNTIME_DIR / 'kiro-cli _ extract-runtime' installs (opt-in layout, kiro-cli 2.37.0+)" "kiro-cli 3.1.0 audit (docs/kiro-3.1.0-wire-audit.md §5, §8 HOST-L2 + orchestrator probe; experiments/conductor-spike/audit-3.1.0/live/host-extract-3.1.0.jsonl, audit-3.1.0/orchestrator/host-defaultdir-3.1.0.jsonl). Since 2.37.0 the host can install node/bun/tui.js/KAS into a shared runtime root: KIRO_RUNTIME_DIR=<dir> or 'kiro-cli _ extract-runtime [--dir]' (helper default <bin>/../lib/kiro-cli), layout <root>/<host-ver>-<hash>/{node,bun,tui.js,.complete,kas/node_modules/@kiro/agent/dist/server/acp-server.js}, siblings pruned; a 'kiro-cli acp' with KIRO_RUNTIME_DIR set spawns node from there and leaves <data dir>/kas empty. LIVE (orchestrator probe): with the env UNSET a plain 3.1.0 'kiro-cli acp' still extracts to <data dir>/kiro-cli/kas/3.1.0-<sha>/ and runs <data dir>/kiro-cli/node — default installs are unaffected. cyril's discovery (crates/cyril-core/src/protocol/kas/discovery.rs:197-200 env reads, :208 search path, :50-53 remedy text) never reads KIRO_RUNTIME_DIR, so a user who set it (or a packaged install that ran extract-runtime) gets 'KAS bundle not found' with a remedy that extracts into the runtime dir again. Opt-in → P3. Fix: honour KIRO_RUNTIME_DIR (absolute-path rule as the host), probe <dir of kiro-cli>/../lib/kiro-cli/<ver>-*/kas, prefer the node beside the bundle, and mention the runtime dir in the remedy. Related cyril-igrx, cyril-d7ve." kas kiro-3-1-0 ready-for-agent
mk N10 3 feature "Clear the remote-MCP OAuth notice on _kiro/mcp/oauthCompleted and read openExternalUrl {serverName, oauthCompletion, oauthFlowId}" "kiro-cli 3.1.0 audit (docs/kiro-3.1.0-wire-audit.md §3, §6 T31). KAS 0.66.91 now sends _kiro/mcp/oauthCompleted {serverName, success, oauthFlowId} after a remote-MCP OAuth flow (0 → 2 literal sites; notifyOAuthCompleted/onLazyAuthCompleted) whenever the client advertised openExternalUrl, and _kiro/openExternalUrl params gain oauthFlowId beside serverName and oauthCompletion (Kiro's TUI consumed this path dark since 2.32.0 — the 3.1.0 line 'MCP sign-in links disappear once their server connects'). cyril advertises openExternalUrl (crates/cyril-core/src/protocol/engine.rs:143), reads only url (crates/cyril-core/src/protocol/kas/callbacks.rs:189-195) and drops the notification at convert/kiro.rs:1305, so the OAuth notice is cleared only by the next _kiro/mcp/status. Opt-in flow (remote MCP with OAuth) → P3; live NOT-REACHED (no OAuth fixture) — static evidence only. Related cyril-tqr8, cyril-nk4o (closed)." kas kiro-3-1-0 ready-for-agent
mk N11 3 bug "cyril-hosted hooks: an executeHook reply with exitCode 2 and empty output does not block the tool on KAS; opt into hooks v2 for PreCompact/PostCompact" "kiro-cli 3.1.0 audit (docs/kiro-3.1.0-wire-audit.md §3, §8 LIVE-D; experiments/conductor-spike/kas-hooks-v2-3.1.0.jsonl, audit-3.1.0/live/kas-lead-hooks31-hookscap-{3.1.0,2.32.0}.jsonl). Two findings. (1) The 3.1.0 line 'PreToolUse hooks that exit 2 block the tool even when they give no reason' holds only for KAS-EXECUTED hooks; a CLIENT-executed hook answered through _kiro/hooks/executeHook with {exitCode:2, output:\"\"} does NOT block on either engine — the tool completes. cyril's host-mode hooks reply {exitCode, output} (crates/cyril-core/src/protocol/kas/hooks.rs:777-781), so a user hook that exits 2 silently is ignored. Fix: synthesize a non-empty output ('blocked by <hook> (exit 2)') when exitCode is 2 and output is empty, or document that hooks must print to block. (2) The v2 hook runtime (standalone .kiro/hooks/*.json, _kiro/hooks/didChange, PreCompact/PostCompact triggers with stdin JSON {compaction_id, reason, message_count, transcript_path, summary, summary_path}) is gated by initialize.clientCapabilities._meta.kiro.hooks:{enabled:true, v2:true}; cyril advertises hooks without v2 (hooks.rs:383), so KAS logs 'v2Hooks is disabled' and PreCompact/PostCompact never run for a cyril session. Fix: send v2:true (Kiro's TUI does) and render the hook_update frames. Opt-in (hooks are configured by the user) → P3. Related cyril-497j." kas kiro-3-1-0 ready-for-agent
mk N12 3 bug "Approval overlay shows a blank preview for KAS skill-load tool calls (raw_input has no string text/content field)" "kiro-cli 3.1.0 audit, live leg 5 S2 on KAS 0.66.91 (experiments/conductor-spike/audit-3.1.0/live/cyril-kas/S2-commands-skill-run.txt, S1-S3-cyril.log). Invoking an advertised skill (/probe-skill hello) makes KAS raise a permission request for the skill-load tool call; cyril's overlay opens with an empty preview and logs WARN 'approval preview raw_input has no string text/content field'. The raw input of that call carries the skill id/path rather than text. Fix: render the skill name (and path) from raw_input when no text/content field exists, so the user knows what they are approving. Reachable on every skill invocation on the default engine; cosmetic but confusing → P3." kas kiro-3-1-0 ready-for-agent
mk N13 4 feature "Always-allow scope page: offer Kiro's '<cmd> <sub> *' subcommand tier" "kiro-cli 3.1.0 audit (docs/kiro-3.1.0-wire-audit.md §6, §8 TUI-L11; experiments/conductor-spike/audit-3.1.0/live/kas-lead-tier-3.1.0.jsonl). Kiro's TUI 2.36.0 adds a rule tier between the exact command and '<cmd> *': subcommandResource = '<argv0> <argv1> *' when argv1 matches ^[A-Za-z][A-Za-z0-9_-]*\$ and argv0 ∉ {sudo, doas, env}; it travels as consent.resource on the permission response. LIVE: the engine accepts any glob identically on 0.66.43 and 0.66.91 (git stash * suppresses the sibling 'git stash show' at session scope and persists as match: [git stash *] at user scope). cyril's echo path already carries any resource (crates/cyril-core/src/protocol/convert/kas.rs:150-191) but always_allow.rs:624-643 derives exact + base pattern only. Cosmetic parity → P4. Related cyril-7c0s, cyril-auxt (closed)." kas kiro-3-1-0 ready-for-agent
mk N14 4 feature "Consult KIRO_DEFAULT_SETTINGS (kiro-cli 3.1.0 root-owned managed defaults) in cyril's settings marshal" "kiro-cli 3.1.0 audit (docs/kiro-3.1.0-wire-audit.md §5, §6 T25). 3.1.0 adds KIRO_DEFAULT_SETTINGS: 'a root-owned, read-only file of default settings that your own cli.json and workspace settings override' (absolute path, regular file, root-owned, not group/other-writable, ≤1 MiB; KIRO_DEFAULT_SETTINGS_SKIP_OWNER_CHECK; chat-cli-v2/src/database/default_settings.rs). Precedence: default file < global cli.json < workspace. cyril's marshal reads only the user cli.json (crates/cyril-core/src/protocol/kas/settings.rs:65), so a managed default such as chat.enableWorkflows=true enables workflows in Kiro's TUI but not in cyril. Low until a managed/CloudShell deployment is in scope → P4. Related cyril-d7ve (KIRO_HOME resolver)." kas kiro-3-1-0 needs-triage
echo "=== parents"; for k in N1 N2 N5; do id=$(awk -v k=$k '$1==k{print $2}' "$OUT"); [ -n "$id" ] && rivets parent set "$id" cyril-c6hv -y 2>&1 | tail -1; done
echo "=== related"; rel() { rivets related add "$1" "$2" -y >/dev/null 2>&1 || true; }
idof() { awk -v k=$1 '$1==k{print $2}' "$OUT"; }
rel "$(idof N1)" cyril-ebqu; rel "$(idof N1)" cyril-1v25; rel "$(idof N2)" cyril-8alk; rel "$(idof N3)" cyril-4u4a; rel "$(idof N4)" cyril-a7nk; rel "$(idof N5)" cyril-xehm; rel "$(idof N9)" cyril-d7ve; rel "$(idof N10)" cyril-tqr8; rel "$(idof N11)" cyril-497j; rel "$(idof N13)" cyril-7c0s
cat "$OUT"
